<!DOCTYPE html>
<html lang="en" dir="ltr">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>Invitation | Digilians Training Program | Darwish &amp; Co.</title>
<meta name="description" content="Digilians training program event. Saturday, 14 November 2026, 9:30 AM, Triumph Plaza Hotel, Heliopolis.">
<meta property="og:title" content="Invitation | Digilians Training Program">
<meta property="og:description" content="Saturday, 14 November 2026, 9:30 AM, Triumph Plaza Hotel, Heliopolis. Register your attendance.">
<meta name="theme-color" content="#0089E6">
<meta name="csrf-token" content="{{ csrf_token() }}">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<style>
:root{
  --blue:#0089E6;--green:#01AB2A;--yellow:#FDD400;--charcoal:#323131;
  --white:#FFFFFF;--gray:#F4F7FA;--line:#E3E9EF;--muted:#6A7078;--danger:#C62F2F;
}
*{box-sizing:border-box;margin:0;padding:0}
body{
  font-family:"Inter","Segoe UI",Arial,sans-serif;background:var(--gray);color:var(--charcoal);
  line-height:1.6;padding:max(28px,env(safe-area-inset-top)) 16px max(36px,env(safe-area-inset-bottom));
}
.wrap{max-width:580px;margin:0 auto}
.card{background:var(--white);border-radius:16px;overflow:hidden;border:1px solid var(--line);box-shadow:0 18px 40px -24px rgba(50,49,49,.25)}
.band{display:flex;height:8px}
.band i:nth-child(1){flex:6;background:var(--blue)}
.band i:nth-child(2){flex:3;background:var(--green)}
.band i:nth-child(3){flex:1;background:var(--yellow)}
.head{padding:44px 32px 8px;text-align:center}
.logo{width:min(340px,82%);min-width:180px;height:auto;display:block;margin:0 auto}

.invite{text-align:center;padding:32px 32px 0}
.lead{color:var(--muted);font-size:16px;font-weight:500}
h1{font-weight:800;font-size:clamp(26px,6vw,34px);line-height:1.2;margin-top:10px;letter-spacing:-.01em}
.desc{font-size:17px;margin-top:14px;max-width:44ch;margin-inline:auto}
.program{font-weight:700;background:linear-gradient(transparent 62%,rgba(253,212,0,.55) 62%);padding:0 2px}

.details{margin:30px 32px 0;background:var(--gray);border-radius:12px;overflow:hidden}
.when{display:grid;grid-template-columns:1fr 1fr}
.when div{padding:18px 10px;text-align:center}
.when div+div{border-left:1px solid var(--line)}
small{display:block;color:var(--muted);font-size:13px;font-weight:500}
.details strong{font-weight:700;font-size:17px}
.where{border-top:1px solid var(--line);padding:18px 22px;text-align:center}
.where strong{display:block}
.addr{font-size:15px;margin-top:2px;color:var(--charcoal)}
.map{display:inline-flex;align-items:center;gap:6px;margin-top:12px;color:var(--blue);font-weight:600;font-size:15px;text-decoration:none}
.map:hover{text-decoration:underline}
.map:focus-visible{outline:2px solid var(--blue);outline-offset:3px;border-radius:4px}
.map svg{width:16px;height:16px}
.dress{
  margin:16px 32px 0;display:flex;align-items:center;gap:16px;
  padding:16px 20px;border-radius:12px;background:var(--charcoal);color:var(--white);
  position:relative;overflow:hidden;
}
.dress::after{content:"";position:absolute;right:0;top:0;bottom:0;width:6px;background:var(--yellow)}
.dress-icon{
  flex:none;width:52px;height:52px;border-radius:50%;
  border:1.5px solid rgba(255,255,255,.35);display:grid;place-items:center;
}
.dress-icon svg{width:28px;height:28px}
.dress small{color:rgba(255,255,255,.7);font-size:13px}
.dress strong{display:block;font-size:20px;font-weight:700;line-height:1.25;letter-spacing:-.01em}
.dress-confirm{max-width:440px;margin:14px auto 0;text-align:left}
.dress p{font-size:14px;color:rgba(255,255,255,.8);margin-top:2px}
@media (max-width:500px){.dress{margin-inline:20px;padding:14px 18px}.dress-confirm{margin-inline:auto}}

form{padding:32px 32px 40px;display:grid;gap:14px}
label{display:block;font-size:15px;font-weight:600;margin-bottom:6px}
.hint{font-size:13px;color:var(--muted);margin-top:6px}
input{width:100%;font:inherit;font-size:17px;color:var(--charcoal);background:var(--white);border:1.5px solid var(--line);border-radius:10px;padding:13px 14px;transition:border-color .15s,box-shadow .15s}
input:focus{outline:none;border-color:var(--blue);box-shadow:0 0 0 3px rgba(0,137,230,.18)}
input[aria-invalid="true"]{border-color:var(--danger)}
.err{color:var(--danger);font-size:13px;margin-top:6px}
.err:empty{display:none}
button{font:inherit;font-weight:700;font-size:17px;cursor:pointer;background:var(--blue);color:var(--white);border:none;border-radius:10px;padding:14px 20px;transition:background .15s}
button:hover{background:#0077C8}
button:focus-visible{outline:3px solid var(--yellow);outline-offset:3px}
button:disabled{opacity:.65;cursor:wait}
.form-msg{text-align:center;font-size:14px;color:var(--danger)}
.form-msg:empty{display:none}

.confirm{padding:32px 32px 40px;text-align:center}
.confirm:not([hidden]){animation:pop .45s ease both}
.confirm h1{margin-top:0;font-size:clamp(28px,7vw,36px)}
.confirm h1:focus{outline:none}
.thanks{font-size:17px;color:var(--muted);margin-top:6px}
#confirmFirst{color:var(--charcoal);font-weight:600}

/* بطاقة الحضور (شكل تذكرة) */
.pass{margin:28px auto 0;max-width:440px;text-align:left;border:1.5px solid var(--line);border-radius:16px;background:var(--white);overflow:hidden}
.pass-top{background:var(--blue);color:var(--white);padding:18px 22px 20px;position:relative}
.pass-top::after{content:"";position:absolute;left:0;right:0;bottom:0;height:4px;
  background:linear-gradient(90deg,var(--green) 0 75%,var(--yellow) 75% 100%)}
.pass-top small{color:rgba(255,255,255,.85);font-size:13px;font-weight:600}
.pass-name{font-size:24px;font-weight:800;line-height:1.25;margin-top:4px;letter-spacing:-.01em;word-break:break-word}
.pass-cut{height:0;border-top:2px dashed var(--line);margin:0 18px;position:relative;top:14px}
.pass-cut::before,.pass-cut::after{content:"";position:absolute;top:-12px;width:22px;height:22px;border-radius:50%;background:var(--white);border:1.5px solid var(--line)}
.pass-cut::before{left:-31px}
.pass-cut::after{right:-31px}
.pass-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px 18px;padding:30px 22px 22px}
.pass-grid .wide{grid-column:1 / -1}
.pass-grid dt{font-size:12px;font-weight:600;color:var(--muted)}
.pass-grid dd{font-size:16px;font-weight:700;line-height:1.35;margin-top:2px}
.pass-grid dd span{display:block;font-weight:400;font-size:14px;color:var(--muted)}

.actions{display:grid;gap:10px;max-width:440px;margin:22px auto 0}
.btn{display:flex;align-items:center;justify-content:center;gap:8px;text-decoration:none;
  font-weight:700;font-size:16px;padding:13px 18px;border-radius:10px;background:var(--blue);color:var(--white);
  border:1.5px solid var(--blue);transition:background .15s}
.btn:hover{background:#0077C8}
.btn-ghost{background:var(--white);color:var(--blue)}
.btn-ghost:hover{background:var(--gray)}
.btn svg{width:18px;height:18px}
.btn:focus-visible,.link:focus-visible{outline:3px solid var(--yellow);outline-offset:3px}
.tip{font-size:14px;color:var(--muted);margin-top:18px}
.link{background:none;border:none;padding:4px;margin-top:6px;color:var(--blue);font-size:15px;font-weight:600;text-decoration:underline;text-underline-offset:3px}
.link:hover{background:none;color:#0077C8}
.check{width:76px;height:76px;margin:0 auto 18px;border-radius:50%;background:var(--green);display:grid;place-items:center}
.check svg{width:38px;height:38px}

.demo{background:#FFF8D6;color:#6B5A00;font-size:14px;text-align:center;padding:8px 16px;display:none}
footer{text-align:center;color:var(--muted);font-size:13px;margin-top:22px}
@keyframes pop{from{opacity:0;transform:scale(.97)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
@media (max-width:500px){.head{padding:36px 20px 4px}form,.invite,.confirm{padding-inline:20px}.pass-grid{padding-inline:18px}.details{margin-inline:20px}}
</style>
</head>
<body>
<div class="wrap">
  <main class="card">
    <div class="band" aria-hidden="true"><i></i><i></i><i></i></div>

    <header class="head">
      <img class="logo" src="data:image/png;base64," alt="Darwish &amp; Co. &mdash; Consulting and Business Development" width="1000" height="243">
    </header>

    <div id="pageInvite">
    <section class="invite">
      <p class="lead">Darwish &amp; Co. cordially invites you to the</p>
      <h1>Digilians Training Program Event</h1>
      <p class="desc">Please register your name below to confirm your attendance.</p>
    </section>

    <section class="details" aria-label="Date, time and venue">
      <div class="when">
        <div><small>Date</small><strong>Saturday, 14 November 2026</strong></div>
        <div><small>Time</small><strong>9:30 AM</strong></div>
      </div>
      <div class="where">
        <small>Venue</small>
        <strong>Omar el Khayam Hall &ndash; 1st Floor</strong>
        <p class="addr">Triumph Plaza Hotel, El-Khalifa El-Maamoun St., Heliopolis, Cairo</p>
        <a class="map" href="https://www.google.com/maps/search/?api=1&amp;query=Triumph+Plaza+Hotel+Heliopolis+Cairo" target="_blank" rel="noopener">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M12 22s7-6.2 7-12a7 7 0 1 0-14 0c0 5.8 7 12 7 12z"/><circle cx="12" cy="10" r="2.5"/></svg>
          Open in Google Maps
        </a>
      </div>
    </section>

    <section class="dress" aria-label="Dress code">
      <div class="dress-icon" aria-hidden="true">
        <svg viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="1.5" stroke-linejoin="round" stroke-linecap="round">
          <path d="M3 21v-8.2c0-1.3.8-2.4 2-2.9L9.5 8 12 11l2.5-3 4.5 1.9c1.2.5 2 1.6 2 2.9V21z"/>
          <path d="M9.5 8l-1.6 4.2 2.6 1.3L12 11"/>
          <path d="M14.5 8l1.6 4.2-2.6 1.3L12 11"/>
          <path d="M12 11l-.9 1.2.9 6.3.9-6.3z" fill="#FDD400" stroke="#FDD400"/>
          <path d="M9.5 8V4.5h5V8"/>
        </svg>
      </div>
      <div>
        <small>Dress code</small>
        <strong>Formal attire</strong>
        <p>Suits or formal business wear</p>
      </div>
    </section>

    <form id="regForm" novalidate>
      <div>
        <label for="full_name">Full name</label>
        <input id="full_name" name="full_name" autocomplete="name" placeholder="Your full name" required>
        <div class="err" id="full_name-err"></div>
      </div>
      <button type="submit" id="submitBtn">Confirm attendance</button>
      <p class="form-msg" id="formMsg" role="alert"></p>
    </form>
    </div>

    <div id="pageConfirm" class="confirm" hidden>
      <div class="check" aria-hidden="true">
        <svg viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12.5l4.5 4.5L19 7.5"/></svg>
      </div>
      <h1 id="confirmTitle" tabindex="-1">You&rsquo;re registered</h1>
      <p class="thanks">Thank you, <span id="confirmFirst"></span>. We look forward to welcoming you.</p>

      <article class="pass" aria-label="Your event details">
        <header class="pass-top">
          <small>Digilians Training Program Event</small>
          <p class="pass-name" id="confirmName"></p>
        </header>
        <div class="pass-cut" aria-hidden="true"></div>
        <dl class="pass-grid">
          <div><dt>Date</dt><dd>Sat, 14 Nov 2026</dd></div>
          <div><dt>Time</dt><dd>9:30 AM</dd></div>
          <div class="wide"><dt>Venue</dt><dd>Omar el Khayam Hall &ndash; 1st Floor<span>Triumph Plaza Hotel, Heliopolis, Cairo</span></dd></div>
        </dl>
      </article>

      <section class="dress dress-confirm" aria-label="Dress code">
        <div class="dress-icon" aria-hidden="true">
          <svg viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="1.5" stroke-linejoin="round" stroke-linecap="round">
            <path d="M3 21v-8.2c0-1.3.8-2.4 2-2.9L9.5 8 12 11l2.5-3 4.5 1.9c1.2.5 2 1.6 2 2.9V21z"/>
            <path d="M9.5 8l-1.6 4.2 2.6 1.3L12 11"/>
            <path d="M14.5 8l1.6 4.2-2.6 1.3L12 11"/>
            <path d="M12 11l-.9 1.2.9 6.3.9-6.3z" fill="#FDD400" stroke="#FDD400"/>
            <path d="M9.5 8V4.5h5V8"/>
          </svg>
        </div>
        <div>
          <small>Dress code</small>
          <strong>Formal attire</strong>
          <p>Suits or formal business wear</p>
        </div>
      </section>

      <div class="actions">
        <a class="btn" id="calBtn" target="_blank" rel="noopener"
           href="https://calendar.google.com/calendar/render?action=TEMPLATE&amp;text=Digilians+Training+Program+Event&amp;dates=20261114T093000/20261114T123000&amp;ctz=Africa/Cairo&amp;location=Omar+el+Khayam+Hall+%E2%80%93+1st+Floor%2C+Triumph+Plaza+Hotel%2C+El-Khalifa+El-Maamoun+St.%2C+Heliopolis%2C+Cairo&amp;details=Hosted+by+Darwish+%26+Co.+Dress+code%3A+formal.">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><rect x="3.5" y="5" width="17" height="15.5" rx="2"/><path d="M3.5 10h17M8 3v4M16 3v4"/></svg>
          Add to Google Calendar
        </a>
        <a class="btn btn-ghost" href="https://www.google.com/maps/search/?api=1&amp;query=Triumph+Plaza+Hotel+Heliopolis+Cairo" target="_blank" rel="noopener">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M12 22s7-6.2 7-12a7 7 0 1 0-14 0c0 5.8 7 12 7 12z"/><circle cx="12" cy="10" r="2.5"/></svg>
          Get directions
        </a>
      </div>
      <p class="tip">Take a screenshot of this page to keep the details handy.</p>
      <button type="button" class="link" id="anotherBtn">Register another name</button>
    </div>
  </main>
  <footer>&copy; 2026 Darwish &amp; Co. &mdash; Consulting and Business Development</footer>
</div>

<script>
const REGISTER_URL = @json(route('register'));
const CSRF = document.querySelector('meta[name="csrf-token"]').content;

const form = document.getElementById("regForm");
const input = document.getElementById("full_name");
const errEl = document.getElementById("full_name-err");
const btn = document.getElementById("submitBtn");
const formMsg = document.getElementById("formMsg");

const pageInvite = document.getElementById("pageInvite");
const pageConfirm = document.getElementById("pageConfirm");

function showConfirm(name){
  document.getElementById("confirmName").textContent = name;
  document.getElementById("confirmFirst").textContent = name.split(" ")[0];
  pageInvite.hidden = true;
  pageConfirm.hidden = false;
  document.title = "You\u2019re registered | Digilians Training Program";
  window.scrollTo(0, 0);
  document.getElementById("confirmTitle").focus({ preventScroll: true });
}

function showInvite(){
  pageConfirm.hidden = true;
  pageInvite.hidden = false;
  document.title = "Invitation | Digilians Training Program | Darwish & Co.";
  form.reset();
  window.scrollTo(0, 0);
  input.focus({ preventScroll: true });
}

document.getElementById("anotherBtn").addEventListener("click", () => {
  try { localStorage.removeItem("dc_registered_name"); } catch (e) {}
  showInvite();
});

// لو الطالب سجّل قبل كده من نفس الموبايل، تظهرله صفحة التأكيد على طول
try {
  const saved = localStorage.getItem("dc_registered_name");
  if (saved) showConfirm(saved);
} catch (e) {}

function setError(msg){
  errEl.textContent = msg || "";
  input.setAttribute("aria-invalid", msg ? "true" : "false");
  if (msg) input.focus();
}

form.addEventListener("submit", async (ev) => {
  ev.preventDefault();
  formMsg.textContent = "";
  const name = input.value.trim().replace(/\s+/g, " ");
  if (name.split(" ").length < 2 || name.length < 3) {
    setError("Enter your first and last name.");
    return;
  }
  if (name.length > 120) { setError("Name is too long. Use up to 120 characters."); return; }
  setError("");

  btn.disabled = true;
  btn.textContent = "Confirming\u2026";
  try {
    const res = await fetch(REGISTER_URL, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Accept": "application/json",
        "X-CSRF-TOKEN": CSRF
      },
      body: JSON.stringify({ full_name: name })
    });
    if (res.status === 422) {
      const body = await res.json();
      setError(body.errors?.full_name?.[0] || "Check your name and try again.");
      return;
    }
    if (res.status === 419) { location.reload(); return; }
    if (res.status === 429) { formMsg.textContent = "Too many attempts. Wait a minute and try again."; return; }
    if (!res.ok) throw new Error(await res.text());
    try { localStorage.setItem("dc_registered_name", name); } catch (e) {}
    showConfirm(name);
  } catch (err) {
    console.error(err);
    formMsg.textContent = "Your attendance wasn\u2019t saved because of a connection problem. Check your internet and select \u201cConfirm attendance\u201d again.";
  } finally {
    btn.disabled = false;
    btn.textContent = "Confirm attendance";
  }
});
</script>
</body>
</html>
